const item = $input.first().json.body ?? $input.first().json;
const columnValues = {
  // TODO: reemplaza estos IDs de columna por los reales del tablero "IMEF" en Monday
  text_whatsapp: item.whatsapp,
  text_grado: item.grado,
  checkbox_confirma_ciclo: item.confirmaCiclo ? "Confirmado" : "",
  text_modalidad: item.modalidad || "",
  status_lead: { label: "Nuevo" }
};
return [{
  json: {
    ...item,
    mondayItemName: item.nombre,
    mondayColumnValues: JSON.stringify(columnValues)
  }
}];
